import {CAREERS,PROGRESSION_SKILLS,careerFor,careerSkillUnlocked,careerUnlockedSkills} from './progression-data-v14.js';
const names={str:'力量',dex:'敏捷',vit:'体质',wis:'精神'};
const growth=c=>Object.entries(c.growth).map(([k,v])=>names[k]+' +'+v).join(' · ');
export function careerPanelHTML(g,{iconHTML,skillDetails}){
 const chosen=careerFor(g.p),options=Object.values(CAREERS).filter(c=>c.cls===g.p.cls),earned=careerUnlockedSkills(g.p).length,preview=!!g.p.career?.preview;
 const detail=c=>`<article class="career-choice ${chosen?.id===c.id?'chosen':''}"><p class="eyebrow">${c.cls==='shadow'?'刃与影':c.cls==='oath'?'钢与誓':'星与烬'}</p><h3>${c.name}</h3><p>${c.summary}</p><div class="note-card"><b>路线固有特性 · ${c.trait}</b><p>${c.traitDesc}</p></div><p class="career-growth">转职后每级：${growth(c)}<br>另获 3 自由属性点、1 技能点。旧等级成长保留。力量、敏捷不提供攻速。</p><div class="career-lessons">${c.skills.filter((k,i)=>chosen?chosen.id===c.id&&careerSkillUnlocked(g.p,k):i===0).map(k=>{const s=PROGRESSION_SKILLS[k],unlocked=chosen?.id===c.id&&careerSkillUnlocked(g.p,k);return `<details class="${unlocked?'earned':'signature'}"><summary>${iconHTML(k)}<span>${s.name}<small>${preview?'回忆中掌握':unlocked?'已掌握':'转职即得'} · ${s.mp} MP · ${s.cd} 秒冷却</small></span></summary><p>${s.description}</p>${!chosen?'<p class="muted">选择此路线后，先从这一招练起。</p>':''}${skillDetails(k)}</details>`;}).join('')}</div>${!chosen?`<button class="primary" data-career="${c.id}">选择${c.name} · 学会${PROGRESSION_SKILLS[c.skills[0]].name}</button>`:''}</article>`;
 return `<div class="modal"><section class="panel career-panel"><header class="panel-head"><div><small>雷昂的传承</small><h2>${chosen?'新的战法 · '+chosen.name:'选择今后的战法'}</h2></div><button data-act="resume">稍后再谈 ×</button></header><div class="panel-body"><p>${preview?'这是 Lv.100 的战法回忆，所学仅在这段回忆中可用，不会带入现实。':chosen?'已掌握 '+earned+' 项转职战技。旧招式仍然保留；新的收获留待旅途中发现。澄心盐与回响墨可以退回自由加点。':'雷昂讲了各路战法的长处，也让你看过它们的起手式。选定后先学一招，路线固有特性随之生效。选择后本章不能改换路线。'}</p><div class="career-options">${(chosen?[chosen]:options).map(detail).join('')}</div>${chosen?`<div class="note-card"><h3>整理已掌握战技</h3><p>同时激活最多五项。快捷整理会加入已经学会的转职战技，并尽量保留旧招式。</p><div class="row"><button data-act="career-equip">整理已掌握战技到快捷栏</button><button class="primary" data-act="career-finish">收好行装，继续听雷昂说</button></div></div>`:''}</div></section></div>`;
}
